contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "not enough balance");

        // Setup: owner opens the contract to the public
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        // Record before state
        uint256 cBalanceBefore = address(c).balance;
        uint256 totalDonatedBefore = address(c).balance; // not directly readable; use balance as proxy

        // Make the deciding call: donate
        c.donate{value: amount}(); if (__ESBMC_reverted()) return;

        // After state
        uint256 cBalanceAfter = address(c).balance;

        // General rule: contract balance unchanged because donation is forwarded to whale
        assert(cBalanceAfter == cBalanceBefore);
    }

    receive() external payable {}
}

